const assert=require('node:assert/strict'),fs=require('node:fs'),os=require('node:os'),path=require('node:path');
const temp=fs.mkdtempSync(path.join(os.tmpdir(),'rating-bundles-'));process.env.DB_FILE=path.join(temp,'test.sqlite');process.env.RATING_EVIDENCE_ROOT=path.join(temp,'datasets');process.env.LOG_TO_FILE='false';process.env.LOG_TO_CONSOLE='false';
const {db,init}=require('../../infrastructure/database');
try{
    init();let bundles;assert.doesNotThrow(()=>{bundles=require('../../modules/ratings/services/ratingResearchBundles');});
    const configuredRoot=process.env.RATING_EVIDENCE_ROOT;delete process.env.RATING_EVIDENCE_ROOT;
    assert.equal(bundles.root(),path.resolve(__dirname,'../../../.private/journey-algorithm-service/datasets'));
    process.env.RATING_EVIDENCE_ROOT=configuredRoot;
    db._raw.prepare("INSERT INTO User(id,username,password) VALUES('u','bundle-user','unused')").run();
    const id=Number(db._raw.prepare("INSERT INTO Place(name) VALUES('test')").run().lastInsertRowid);
    const evidence=require('../../modules/ratings/services/ratingEvidence');evidence.recordResearchChoice('u',true);
    require('../../modules/preferences/services/userPreferenceService').changeFavorite('u',id,true);
    const preview=bundles.exportBundle({secret:'s'.repeat(32)});assert.equal(preview.applied,false);assert.equal(fs.existsSync(process.env.RATING_EVIDENCE_ROOT),false,'dry-run must not create a directory');
    process.env.RATING_EVIDENCE_EXPORT_ENABLED='true';
    const created=bundles.exportBundle({apply:true,secret:'s'.repeat(32)});assert.equal(created.applied,true);
    const file=path.join(process.env.RATING_EVIDENCE_ROOT,`${created.id}.json`);assert.ok(fs.existsSync(file));assert.equal(bundles.bundleStatus(created.id).valid,true);
    evidence.recordResearchChoice('u',false);assert.equal(bundles.bundleStatus(created.id).valid,false,'revocation invalidates before filesystem deletion');
    const remove=fs.rmSync;fs.rmSync=(target,options)=>{if(target===file)throw Object.assign(Error('temporary lock'),{code:'EACCES'});return remove(target,options);};
    try{assert.equal(bundles.purgeBundles().failed,1);assert.equal(bundles.bundleStatus(created.id).valid,false);}finally{fs.rmSync=remove;}
    assert.equal(bundles.purgeBundles().deleted,1);assert.equal(fs.existsSync(file),false);
    db._raw.prepare("INSERT INTO User(id,username,password) VALUES('unconsented','original-author','unused')").run();
    const revisions=require('../../modules/places/services/placeRevisions');
    db._raw.prepare('UPDATE Place SET description=? WHERE id=?').run('unconsented original text',id);
    revisions.recordPlaceRevision({placeId:id,authorId:'unconsented',path:'create'});
    evidence.recordResearchChoice('u',true);
    let before=db._raw.prepare('SELECT * FROM Place WHERE id=?').get(id);
    db._raw.prepare('UPDATE Place SET per_person_cost=10 WHERE id=?').run(id);
    revisions.recordPlaceRevision({placeId:id,authorId:'u',path:'owner_edit',before});
    assert.equal(bundles.exportBundle({secret:'s'.repeat(32)}).description_count,0,'a price edit must not claim authorship of another person\'s description');
    before=db._raw.prepare('SELECT * FROM Place WHERE id=?').get(id);
    db._raw.prepare('UPDATE Place SET description=? WHERE id=?').run('unconsented original text本人追加内容',id);
    const contribution=revisions.recordPlaceRevision({placeId:id,authorId:'u',path:'owner_edit',before});
    const history=require('../../modules/ratings/services/ratingHistory');
    history.appendRatingRevision({userId:'u',placeId:id,before:null,after:{score:4,source:'create',created_at:Date.now(),updated_at:Date.now()},action:'create',origin:'creation_explicit',surface:'web'});
    const recorded=db._raw.prepare("SELECT * FROM RatingRevision WHERE user_id='u' ORDER BY rowid DESC LIMIT 1").get();
    assert.equal(recorded.experience_time_basis,'submission','an explicit creation score is a first rating submission');
    const decisionId='bundle-decision-123456';
    db._raw.prepare('INSERT INTO MapDecision(id,user_id,request_hash,snapshot,result,created_at) VALUES(?,?,?,?,?,?)').run(decisionId,'u','fixture',JSON.stringify({algorithm:'random-mixture-v1',policy_version:'random-mixture-v1',feature_snapshot_version:1,display_version:'rating-summary-v1',selected_probability:1,candidates:[{place_id:id,probability:1}],private_text:'do-not-export',latitude:30}),'{}',new Date().toISOString());
    db._raw.prepare("INSERT INTO MapInteraction(id,user_id,session_id,kind,surface,decision_id,place_id,research_allowed,created_at) VALUES('bundle-click-123456','u','session','click','random',?,?,1,?)").run(decisionId,id,new Date().toISOString());
    evidence.captureEvent('MapInteraction','u','bundle-click-123456',{trigger:'user',surface:'random',decisionId});
    const rewritten=bundles.exportBundle({apply:true,secret:'s'.repeat(32)});
    const payload=JSON.parse(fs.readFileSync(path.join(process.env.RATING_EVIDENCE_ROOT,`${rewritten.id}.json`),'utf8'));
    assert.equal(payload.description_revisions.length,1);assert.equal(payload.description_revisions[0].id,contribution);
    assert.equal(payload.description_revisions[0].after_description,null);
    assert.equal(payload.description_revisions[0].contribution_text,'本人追加内容','an append exports only the actual author\'s addition');
    assert.ok(!JSON.stringify(payload).includes('unconsented original text'),'unproven predecessor text must never be exported');
    assert.equal(payload.rating_revisions[0].entry_surface,'web');assert.equal(payload.rating_revisions[0].rating_scale_version,1);
    assert.equal(payload.reason_links[0].place_revision_id,contribution);
    assert.equal(payload.decisions[0].policy_version,'random-mixture-v1');assert.deepEqual(payload.decisions[0].candidates,[{place_id:id,rank:null,probability:1}]);
    assert.ok(!JSON.stringify(payload).includes('do-not-export'),'decision export uses an explicit field allowlist');
    const mixedBefore=db._raw.prepare('SELECT * FROM Place WHERE id=?').get(id);
    db._raw.prepare('UPDATE Place SET description=? WHERE id=?').run('本人修改unconsented original text中间内容',id);
    const mixed=revisions.recordPlaceRevision({placeId:id,authorId:'u',path:'owner_edit',before:mixedBefore});
    const mixedBundle=bundles.exportBundle({apply:true,secret:'s'.repeat(32)}),mixedData=JSON.parse(fs.readFileSync(path.join(process.env.RATING_EVIDENCE_ROOT,`${mixedBundle.id}.json`),'utf8'));
    const uncertain=mixedData.description_revisions.find(r=>r.id===mixed);assert.equal(uncertain.text_basis,'mixed_or_replaced_unresolved');assert.equal(uncertain.contribution_text,null);
    assert.ok(!JSON.stringify(mixedData).includes('unconsented original text'),'arbitrary mixed replacements retain metadata without leaking predecessor text');
    db._raw.prepare('DELETE FROM Place WHERE id=?').run(id);assert.equal(bundles.bundleStatus(rewritten.id).valid,false,'place deletion invalidates the bundle before its cleanup retry');
    assert.throws(()=>bundles.exportBundle({apply:true,secret:'s'.repeat(32),output:path.resolve(temp,'escape')}),/受控/);
    console.log('Research bundles: dry-run, pseudonymized export, status, revoke-before-delete and path bounds passed.');
}finally{require('../../modules/preferences/services/userPreferenceService').startUserVectorWorker()();db._raw.close();fs.rmSync(temp,{recursive:true,force:true});}
